def longest_balanced_subarray(n, arr):
    from collections import defaultdict

    prefix_sum = 0
    sum_indices = defaultdict(list)
    max_len = -1

    # Store the first occurrence index of each prefix sum
    sum_indices[0].append(-1)  # To handle subarrays starting from index 0

    for i in range(n):
        prefix_sum += arr[i]
        if prefix_sum in sum_indices:
            # Calculate the length of subarray between two indices
            for idx in sum_indices[prefix_sum]:
                length = i - idx
                if length > max_len:
                    max_len = length
        else:
            sum_indices[prefix_sum].append(i)

    return max_len if max_len != 0 else -1
