def longest_balanced_subarray(n, arr):
    # Calculate prefix sums
    prefix_sum = []
    current_sum = 0
    for num in arr:
        current_sum += num
        prefix_sum.append(current_sum)

    # Dictionary to store the last index where a prefix sum was seen
    seen = {}
    max_len = -1
    for i in range(n):
        if prefix_sum[i] in seen:
            # Calculate the length of the subarray
            length = i - seen[prefix_sum[i]]
            if length > max_len:
                max_len = length
        else:
            seen[prefix_sum[i]] = i

    # After processing, check if there's any subarray with sum 0
    if max_len == -1:
        return -1
    else:
        return max_len
